STYLE = '\n:root{--ink:#263c37;--muted:#586660;--paper:#faf7f0;--white:#fffefb;--green:#235a4d;--pale:#eaf0e7;--line:#d9ded2;--gold:#e6b869}\n*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:18px/1.7 Georgia,serif;display:flex}\na{color:var(--green);text-underline-offset:3px}a:hover{color:#102e26}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid #a56521;outline-offset:4px}\n.sidebar{width:252px;min-width:252px;padding:30px 22px;height:100vh;position:sticky;top:0;overflow:auto;background:var(--white);border-right:1px solid var(--line);font:15px/1.5 system-ui,sans-serif}\n.brand{display:block;font:700 23px/1.2 Georgia,serif;margin-bottom:6px;text-decoration:none}.tag{color:var(--muted);font-size:12px;margin:0 0 28px}.sidebar ul{list-style:none;padding:0;margin:10px 0 23px}.sidebar li{margin:3px 0}\n.sidebar li a{display:block;padding:7px 10px;border-radius:6px;text-decoration:none}.sidebar a[aria-current]{background:var(--pale);font-weight:650}\n.navlabel{font-size:11px;letter-spacing:.13em;text-transform:uppercase;color:var(--muted)}summary{cursor:pointer;font-family:system-ui,sans-serif;font-size:14px;font-weight:600}\n.sidebar details{border-top:1px solid var(--line);padding:14px 0}.sidebar details ul{margin-bottom:2px}.sidebar details details{border:0}\n.content{width:100%;max-width:920px;margin:auto;padding:55px 58px 65px;min-width:0}.eyebrow{text-transform:uppercase;letter-spacing:.12em;font:600 11px/1.6 system-ui,sans-serif;color:var(--green);margin:0 0 18px}\nh1{font:normal 48px/1.12 Georgia,serif;letter-spacing:-.025em;margin:0 0 24px;max-width:720px}h2{font:normal 27px/1.25 Georgia,serif;margin:36px 0 12px}h3{font-size:21px;margin-top:26px}p{margin:12px 0 18px}.lede{font-size:23px;line-height:1.5;color:#455b52;max-width:650px}\n.welcome{background:var(--pale);border:1px solid #d0dbce;border-radius:14px;padding:22px 28px;margin:30px 0}.welcome h2{margin-top:0}.welcome p:last-child{margin-bottom:0}\n.button{display:inline-block;background:var(--green);color:white!important;padding:12px 20px;border-radius:7px;font:600 15px/1.5 system-ui,sans-serif;text-decoration:none;margin:10px 0}\n.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:30px 0}.steps div{border-top:3px solid var(--gold);padding-top:14px}.steps b{font:600 14px/1.5 system-ui,sans-serif}.steps p{font-size:16px;line-height:1.5}\n.small,.pagefoot{font:13px/1.6 system-ui,sans-serif;color:var(--muted)}.pagefoot{border-top:1px solid var(--line);padding-top:22px;margin-top:48px}\n.prompt{background:var(--white);border:1px solid #c8d4c9;border-radius:10px;margin:20px 0 24px;overflow:hidden}.promptbar{padding:10px 16px;background:var(--pale);display:flex;align-items:center;justify-content:space-between;gap:12px;font:12px/1.4 system-ui,sans-serif;color:var(--muted)}\n.copy{background:var(--green);color:#fff;border:0;border-radius:5px;padding:8px 12px;cursor:pointer;font:600 12px system-ui,sans-serif;white-space:nowrap}\npre{white-space:pre-wrap;overflow-wrap:anywhere;margin:0;padding:20px;font:15px/1.65 system-ui,sans-serif}pre code{font:inherit}code{font:14px/1.5 Consolas,monospace;overflow-wrap:anywhere}\n.copy-status{display:block;font:12px/1.5 system-ui,sans-serif;padding:0 16px}.copy-status:not(:empty){padding-bottom:12px}\ntable{border-collapse:collapse;width:100%;margin:22px 0;font-size:16px}th,td{text-align:left;vertical-align:top;border-bottom:1px solid var(--line);padding:12px}th{background:var(--pale);font:600 13px/1.5 system-ui,sans-serif}\nblockquote{border-left:3px solid var(--gold);padding:5px 20px;margin:24px 0;color:#46574e}li{margin:7px 0}\n.content details{border:1px solid var(--line);border-radius:8px;padding:16px 20px;margin:18px 0;background:var(--white)}.content details[open] summary{margin-bottom:16px}\n.sample{padding:10px 0}.sample h1{font-size:28px}.sample h2{font-size:23px}.notice{font:14px/1.6 system-ui,sans-serif;background:var(--pale);padding:15px 20px;border-radius:8px;margin-bottom:28px}\n.skip{position:absolute;left:-9999px}.skip:focus{left:16px;top:16px;z-index:10;background:white;padding:12px}\n@media(max-width:1000px){.content{padding:40px 32px}.sidebar{width:218px;min-width:218px}h1{font-size:42px}}\n@media(max-width:720px){body{display:block}.sidebar{width:100%;height:auto;position:static;padding:20px;border-right:0;border-bottom:1px solid var(--line)}.tag{margin-bottom:12px}.sidebar ul{display:flex;flex-wrap:wrap;gap:4px;margin-bottom:12px}.sidebar details ul{display:block}.sidebar li a{padding:6px 8px}.content{padding:30px 22px 45px}h1{font-size:37px}.lede{font-size:21px}.steps{grid-template-columns:1fr;gap:6px}.welcome{padding:22px}th,td{padding:8px;font-size:14px}}\n@media print{body{display:block;background:#fff}.sidebar,.copy,.skip{display:none}.content{max-width:none;padding:0}.prompt{break-inside:avoid}a{color:#000}.pagefoot{font-size:10px}}\n'
SCRIPT = "\ndocument.querySelectorAll('.copy').forEach(button => {\n  button.addEventListener('click', async () => {\n    const box = button.closest('.prompt');\n    const text = box.querySelector('code').textContent;\n    const status = box.querySelector('.copy-status');\n    let copied = false;\n    try {\n      if (navigator.clipboard && window.isSecureContext) {\n        await navigator.clipboard.writeText(text);\n        copied = true;\n      }\n    } catch (_) {}\n    if (!copied) {\n      const field = document.createElement('textarea');\n      field.value = text;\n      field.style.position = 'fixed';\n      field.style.top = '0';\n      field.style.left = '-9999px';\n      document.body.appendChild(field);\n      field.select();\n      try { copied = document.execCommand('copy'); } catch (_) {}\n      field.remove();\n      button.focus();\n    }\n    status.textContent = copied ? 'Copied. Paste it into your AI conversation.' : 'Select the prompt text and copy it with Ctrl+C (Windows) or Command+C (Mac).';\n  });\n});\n"
